    struct CurrentDirGuard {
        previous: PathBuf,
    }

    impl CurrentDirGuard {
        fn enter(dir: &std::path::Path) -> Self {
            let previous = std::env::current_dir().unwrap();
            std::env::set_current_dir(dir).unwrap();
            Self { previous }
        }
    }

    impl Drop for CurrentDirGuard {
        fn drop(&mut self) {
            let _ = std::env::set_current_dir(&self.previous);
        }
    }

    struct EnvVarGuard {
        name: &'static str,
        original: Option<OsString>,
    }

    impl EnvVarGuard {
        fn set(name: &'static str, value: OsString) -> Self {
            let original = std::env::var_os(name);
            unsafe {
                std::env::set_var(name, value);
            }
            Self { name, original }
        }
    }

    impl Drop for EnvVarGuard {
        fn drop(&mut self) {
            match self.original.take() {
                Some(value) => unsafe {
                    std::env::set_var(self.name, value);
                },
                None => unsafe {
                    std::env::remove_var(self.name);
                },
            }
        }
    }

    fn completion_values(
        candidates: Vec<clap_complete::engine::CompletionCandidate>,
    ) -> Vec<String> {
        candidates
            .into_iter()
            .map(|candidate| candidate.get_value().to_string_lossy().to_string())
            .collect()
    }

    #[cfg(unix)]
    fn write_fake_command(bin_dir: &std::path::Path, name: &str, body: &str) -> std::path::PathBuf {
        let path = bin_dir.join(name);
        fs::write(&path, body).expect("write fake command");
        use std::os::unix::fs::PermissionsExt;
        let mut permissions = fs::metadata(&path)
            .expect("fake command metadata")
            .permissions();
        permissions.set_mode(0o755);
        fs::set_permissions(&path, permissions).expect("make fake command executable");
        path
    }

    #[cfg(windows)]
    fn write_fake_command(bin_dir: &std::path::Path, name: &str, body: &str) -> std::path::PathBuf {
        let path = bin_dir.join(name);
        fs::write(&path, body).expect("write fake command");
        path
    }

    fn shell_completion_values(
        words: &[&str],
        arg_index: usize,
    ) -> Result<Vec<String>, std::io::Error> {
        let mut command = completion_command();
        let current_dir = std::env::current_dir().ok();
        let args = words
            .iter()
            .map(|word| OsString::from(*word))
            .collect::<Vec<_>>();
        clap_complete::engine::complete(&mut command, args, arg_index, current_dir.as_deref())
            .map(completion_values)
    }

    #[cfg(unix)]
    fn install_fake_docker(path: &std::path::Path) {
        let name = path
            .file_name()
            .and_then(|entry| entry.to_str())
            .unwrap_or("docker");
        let dir = path.parent().unwrap_or_else(|| Path::new("."));
        write_fake_command(
            dir,
            name,
            r#"#!/bin/sh
state_dir="$(dirname "$0")/docker-state"
mkdir -p "$state_dir"
if [ -n "$OTA_FAKE_DOCKER_TRACE" ]; then
  printf '%s\n' "$@" >> "$OTA_FAKE_DOCKER_TRACE"
fi

command="$1"
shift

case "$command" in
  --version|version)
    printf 'Docker version 29.3.1, build deadbeef\n'
    exit 0
    ;;
  info)
    exit 0
    ;;
  ps)
    label_filter=""
    want_stale=0
    format=""
    while [ "$#" -gt 0 ]; do
      case "$1" in
        -a)
          shift
          ;;
        --filter)
          case "$2" in
            label=*)
              label_filter="${2#label=}"
              ;;
            status=exited|status=dead)
              want_stale=1
              ;;
          esac
          shift 2
          ;;
        --format)
          format="$2"
          shift 2
          ;;
        *)
          shift
          ;;
      esac
    done
    for path_file in "$state_dir"/*.path; do
      [ -e "$path_file" ] || continue
      name=$(basename "$path_file" .path)
      if [ "$want_stale" = "1" ] && [ -f "$state_dir/$name.running" ]; then
        continue
      fi
      if [ -n "$label_filter" ]; then
        [ -f "$state_dir/$name.labels" ] || continue
        grep -Fx "$label_filter" "$state_dir/$name.labels" >/dev/null || continue
      fi
      if [ "$format" = "{{.Names}}" ]; then
        printf "%s\n" "$name"
      else
        printf "%s\n" "$name"
      fi
    done
    exit 0
    ;;
  inspect)
    if [ "$1" = "-f" ]; then
      format="$2"
      name="$3"
      [ -f "$state_dir/$name.path" ] || exit 1
      if [ "$format" = "{{.State.Running}}" ]; then
        if [ -f "$state_dir/$name.running" ]; then
          printf "true\n"
        else
          printf "false\n"
        fi
        exit 0
      fi
      if [ "$format" = "{{json .NetworkSettings.Networks}}" ]; then
        if [ -f "$state_dir/$name.networks" ]; then
          first=1
          printf "{"
          while IFS= read -r network; do
            [ -n "$network" ] || continue
            if [ "$first" = "1" ]; then
              first=0
            else
              printf ","
            fi
            printf "\"%s\":{}" "$network"
          done < "$state_dir/$name.networks"
          printf "}\n"
        else
          printf "{}\n"
        fi
        exit 0
      fi
      if [ "$format" = "{{json .Config.Labels}}" ]; then
        if [ -f "$state_dir/$name.labels" ]; then
          labels_json="{"
          first_label=1
          while IFS= read -r label_entry; do
            [ -n "$label_entry" ] || continue
            key="${label_entry%%=*}"
            value="${label_entry#*=}"
            if [ "$first_label" = "1" ]; then
              first_label=0
            else
              labels_json="${labels_json},"
            fi
            labels_json="${labels_json}\"$key\":\"$value\""
          done < "$state_dir/$name.labels"
          labels_json="${labels_json}}"
          printf "%s\n" "$labels_json"
        else
          printf "null\n"
        fi
        exit 0
      fi
      if [ "$format" = "{{json .Mounts}}" ]; then
        host_dir=$(cat "$state_dir/$name.path")
        mounts_json='[{"Type":"bind","Source":"'"$host_dir"'","Destination":"/workspace"}'
        if [ -f "$state_dir/$name.mounts" ]; then
          while IFS= read -r mount_entry; do
            [ -n "$mount_entry" ] || continue
            mount_source="${mount_entry%%:*}"
            mount_destination="${mount_entry#*:}"
            case "$mount_destination" in
              /workspace)
                ;;
              *)
                mounts_json="${mounts_json},{\"Type\":\"volume\",\"Name\":\"$mount_source\",\"Source\":\"$state_dir/volume.$mount_source\",\"Destination\":\"$mount_destination\"}"
                ;;
            esac
          done < "$state_dir/$name.mounts"
        fi
        mounts_json="${mounts_json}]"
        printf "%s\n" "$mounts_json"
        exit 0
      fi
      exit 1
    fi
    name="$1"
    [ -f "$state_dir/$name.path" ]
    exit $?
    ;;
  port)
    name="$1"
    query="$2"
    [ -f "$state_dir/$name.path" ] || exit 1
    if [ -f "$state_dir/$name.publish" ]; then
      while IFS= read -r publication; do
        [ -n "$publication" ] || continue
        transport="${publication##*/}"
        publication="${publication%/*}"
        if printf "%s" "$publication" | grep -q "::"; then
          host_address="${publication%%::*}"
          bind_port="${publication##*::}"
          host_port="49153"
        else
          host_address="${publication%%:*}"
          remainder="${publication#*:}"
          host_port="${remainder%%:*}"
          bind_port="${remainder##*:}"
        fi
        if [ "$bind_port/$transport" = "$query" ]; then
          printf "%s:%s\n" "$host_address" "$host_port"
          exit 0
        fi
      done < "$state_dir/$name.publish"
    fi
    exit 1
    ;;
  start)
    attach=0
    while [ "$#" -gt 0 ]; do
      case "$1" in
        -a|-i|-ai|-ia)
          attach=1
          shift
          ;;
        *)
          name="$1"
          shift
          break
          ;;
      esac
    done
    [ -f "$state_dir/$name.path" ] || exit 1
    host_dir=$(cat "$state_dir/$name.path")
    printf "start\n" >> "$host_dir/docker-log.txt"
    : > "$state_dir/$name.running"
    if [ "$attach" = "1" ] && [ -f "$state_dir/$name.command" ]; then
      if [ -f "$state_dir/$name.env" ]; then
        while IFS= read -r env_entry; do
          [ -n "$env_entry" ] || continue
          export "$env_entry"
        done < "$state_dir/$name.env"
      fi
      cd "$host_dir" || exit 1
      exec /bin/sh "$state_dir/$name.command"
    fi
    exit 0
    ;;
  exec)
    while [ "$#" -gt 0 ]; do
      case "$1" in
        -i)
          shift
          ;;
        --env)
          export "$2"
          shift 2
          ;;
        *)
          name="$1"
          shift
          break
          ;;
      esac
    done
    host_dir=$(cat "$state_dir/$name.path")
    printf "exec\n" >> "$host_dir/docker-log.txt"
    if [ "$1" = "sh" ] && [ "$2" = "-s" ]; then
      shift 2
      [ "$1" = "--" ] && shift
      cd "$host_dir" || exit 1
      exec /bin/sh -s -- "$@" < /dev/stdin
    fi
    if [ "$1" = "sh" ] && [ "$2" = "-c" ]; then
      case "$3" in
        *"/proc/net/tcp"*)
          if [ -f "$state_dir/$name.proc-net" ]; then
            cat "$state_dir/$name.proc-net"
          fi
          exit 0
          ;;
      esac
    fi
    cd "$host_dir" || exit 1
    exec /bin/sh -c "$3"
    ;;
  create)
    mount=""
    workspace_mount=""
    mounts=""
    name=""
    network=""
    labels=""
    env_entries=""
    pub_entries=""
    while [ "$#" -gt 0 ]; do
      case "$1" in
        --rm|-i)
          shift
          ;;
        --label)
          labels="${labels}${2}
"
          shift 2
          ;;
        --entrypoint)
          shift 2
          ;;
        --name)
          name="$2"
          shift 2
          ;;
        --network)
          network="$2"
          shift 2
          ;;
        -v)
          mount="$2"
          mounts="${mounts}${2}
"
          case "$2" in
            *:/workspace)
              workspace_mount="$2"
              ;;
          esac
          shift 2
          ;;
        -w)
          shift 2
          ;;
        -p)
          pub_entries="${pub_entries}${2}
"
          shift 2
          ;;
        --env)
          case "$2" in
            *=*)
              env_entries="${env_entries}${2}
"
              ;;
            *)
              env_entries="${env_entries}${2}=$(printenv "$2")
"
              ;;
          esac
          shift 2
          ;;
        *)
          image="$1"
          shift
          break
          ;;
      esac
    done
    host_dir="${workspace_mount%%:*}"
    printf "%s" "$mounts" > "$host_dir/docker-mounts.txt"
    printf "%s" "$host_dir" > "$state_dir/$name.path"
    printf "%s" "$image" > "$host_dir/docker-image.txt"
    if [ -n "$network" ]; then
      printf "%s\n" "$network" > "$state_dir/$name.networks"
    else
      : > "$state_dir/$name.networks"
    fi
    printf "%s" "$mounts" > "$state_dir/$name.mounts"
    if [ -n "$env_entries" ]; then
      printf "%s" "$env_entries" > "$state_dir/$name.env"
    else
      : > "$state_dir/$name.env"
    fi
    if [ -n "$labels" ]; then
      printf "%s" "$labels" > "$state_dir/$name.labels"
    else
      : > "$state_dir/$name.labels"
    fi
    if [ -n "$pub_entries" ]; then
      printf "%s" "$pub_entries" > "$state_dir/$name.publish"
    else
      : > "$state_dir/$name.publish"
    fi
    if [ "$1" = "-c" ] || [ "$1" = "-lc" ]; then
      printf "%s" "$2" > "$state_dir/$name.command"
    elif [ "$1" = "sh" ] && [ "$2" = "-c" ]; then
      printf "%s" "$3" > "$state_dir/$name.command"
    elif [ "$1" = "sh" ] && [ "$2" = "-lc" ]; then
      printf "%s" "$3" > "$state_dir/$name.command"
    else
      printf "%s" "$1" > "$state_dir/$name.command"
    fi
    printf "run-ephemeral\n" >> "$host_dir/docker-log.txt"
    exit 0
    ;;
  run)
    detached=0
    mount=""
    workspace_mount=""
    mounts=""
    name=""
    labels=""
    network=""
    pub_entries=""
    while [ "$#" -gt 0 ]; do
      case "$1" in
        -d)
          detached=1
          shift
          ;;
        --rm|-i)
          shift
          ;;
        --entrypoint)
          shift 2
          ;;
        --name)
          name="$2"
          shift 2
          ;;
        --label)
          labels="${labels}${2}
"
          shift 2
          ;;
        --network)
          network="$2"
          shift 2
          ;;
        -v)
          mount="$2"
          mounts="${mounts}${2}
"
          case "$2" in
            *:/workspace)
              workspace_mount="$2"
              ;;
          esac
          shift 2
          ;;
        -w)
          shift 2
          ;;
        -p)
          pub_entries="${pub_entries}${2}
"
          shift 2
          ;;
        --env)
          export "$2"
          shift 2
          ;;
        *)
          image="$1"
          shift
          break
          ;;
      esac
    done
    host_dir="${workspace_mount%%:*}"
    printf "%s" "$mounts" > "$host_dir/docker-mounts.txt"
    printf "%s" "$image" > "$host_dir/docker-image.txt"
    if [ "$detached" = "1" ]; then
      printf "%s" "$host_dir" > "$state_dir/$name.path"
      printf "%s" "$mounts" > "$state_dir/$name.mounts"
      : > "$state_dir/$name.running"
      if [ -n "$network" ]; then
        printf "%s\n" "$network" > "$state_dir/$name.networks"
      else
        : > "$state_dir/$name.networks"
      fi
      if [ -n "$labels" ]; then
        printf "%s" "$labels" > "$state_dir/$name.labels"
      fi
      if [ -n "$pub_entries" ]; then
        printf "%s" "$pub_entries" > "$state_dir/$name.publish"
      else
        : > "$state_dir/$name.publish"
      fi
      printf "run-persistent\n" >> "$host_dir/docker-log.txt"
      exit 0
    fi
    if [ -n "$pub_entries" ]; then
      printf "%s" "$pub_entries" > "$state_dir/$name.publish"
    else
      : > "$state_dir/$name.publish"
    fi
    printf "run-ephemeral\n" >> "$host_dir/docker-log.txt"
    cd "$host_dir" || exit 1
    if [ "$1" = "-c" ] || [ "$1" = "-lc" ]; then
      exec /bin/sh -c "$2"
    fi
    if [ "$1" = "sh" ] && [ "$2" = "-c" ]; then
      exec /bin/sh -c "$3"
    fi
    if [ "$1" = "sh" ] && [ "$2" = "-lc" ]; then
      exec /bin/sh -c "$3"
    fi
    exec /bin/sh -c "$1"
    ;;
  network)
    [ "$1" = "connect" ] || exit 1
    network="$2"
    name="$3"
    [ -f "$state_dir/$name.path" ] || exit 1
    touch "$state_dir/$name.networks"
    grep -Fx "$network" "$state_dir/$name.networks" >/dev/null || printf "%s\n" "$network" >> "$state_dir/$name.networks"
    exit 0
    ;;
  volume)
    subcommand="$1"
    shift
    case "$subcommand" in
      inspect)
        volume_name="$1"
        [ -f "$state_dir/volume.$volume_name" ] || exit 1
        exit 0
        ;;
      ls)
        [ "$1" = "-q" ] && shift
        for volume_path in "$state_dir"/volume.*; do
          [ -e "$volume_path" ] || continue
          printf "%s\n" "${volume_path##*/volume.}"
        done
        exit 0
        ;;
      create)
        volume_name="$1"
        : > "$state_dir/volume.$volume_name"
        printf "%s\n" "$volume_name"
        exit 0
        ;;
      rm)
        [ "$1" = "-f" ] && shift
        volume_name="$1"
        [ -f "$state_dir/volume.$volume_name" ] || exit 1
        rm -f "$state_dir/volume.$volume_name"
        exit 0
        ;;
    esac
    exit 1
    ;;
  rm)
    shift
    [ "$1" = "-f" ] && shift
    name="$1"
    [ -f "$state_dir/$name.path" ] || exit 1
    host_dir=$(cat "$state_dir/$name.path")
    rm -f "$state_dir/$name.path"
    rm -f "$state_dir/$name.running"
    rm -f "$state_dir/$name.labels"
    rm -f "$state_dir/$name.networks"
    rm -f "$state_dir/$name.mounts"
    rm -f "$state_dir/$name.command"
    rm -f "$state_dir/$name.env"
    printf "rm\n" >> "$host_dir/docker-log.txt"
    exit 0
    ;;
esac

exit 1
"#,
        );
    }

    #[cfg(unix)]
    fn install_fake_docker_without_port_reporting(path: &std::path::Path) {
        let real_path = path.with_file_name("docker-real");
        install_fake_docker(&real_path);
        fs::write(
            path,
            format!(
                r#"#!/bin/sh
if [ "$1" = "port" ]; then
  exit 1
fi
exec "{}" "$@"
"#,
                real_path.display()
            ),
        )
        .unwrap();
        use std::os::unix::fs::PermissionsExt;
        let mut permissions = fs::metadata(path).unwrap().permissions();
        permissions.set_mode(0o755);
        fs::set_permissions(path, permissions).unwrap();
    }

    #[cfg(unix)]
    fn install_fake_empty_container_engine(path: &std::path::Path, name: &str) {
        fs::write(
            path,
            format!(
                r#"#!/bin/sh
case "$1" in
  --version|version)
    printf '{name} version 1.0.0\n'
    exit 0
    ;;
  info|ps)
    exit 0
    ;;
esac
exit 1
"#
            ),
        )
        .unwrap();
    }

    #[cfg(unix)]
    fn install_fake_cargo(path: &std::path::Path) {
        fs::write(
            path,
            r#"#!/bin/sh
if [ "$1" = "--version" ]; then
  echo "cargo 1.99.0"
  exit 0
fi
exit 1
"#,
        )
        .unwrap();

        use std::os::unix::fs::PermissionsExt;
        let mut permissions = fs::metadata(path).unwrap().permissions();
        permissions.set_mode(0o755);
        fs::set_permissions(path, permissions).unwrap();
    }

    #[cfg(unix)]
    fn install_fake_daytona(path: &std::path::Path) {
        fs::write(
            path,
            r#"#!/bin/sh
command="$1"
shift

case "$command" in
  exec)
    target="$1"
    shift
    cwd=""
    if [ "$1" = "--cwd" ]; then
      cwd="$2"
      shift 2
    fi
    [ "$1" = "--" ] || exit 1
    shift
    [ -n "$cwd" ] || exit 1
    printf "exec %s\n" "$target" >> "$cwd/daytona-log.txt"
    cd "$cwd" || exit 1
    exec /bin/sh -lc "$3"
    ;;
esac

exit 1
"#,
        )
        .unwrap();
    }

    #[cfg(unix)]
    fn install_fake_ssh(path: &std::path::Path) {
        fs::write(
            path,
            r#"#!/bin/sh
target=""
while [ "$#" -gt 0 ]; do
  case "$1" in
    -F|-i)
      [ "$#" -ge 2 ] || exit 1
      shift 2
      ;;
    -*)
      shift
      ;;
    *)
      target="$1"
      shift
      break
      ;;
  esac
done
[ -n "$target" ] || exit 1
[ "$#" -ge 1 ] || exit 1
printf "exec %s\n" "$target" >> "$OTA_SSH_LOG"
exec /bin/sh -lc "$*"
"#,
        )
        .unwrap();
    }

    #[cfg(unix)]
    struct FakeSshGuard {
        original_path: Option<std::ffi::OsString>,
        original_log: Option<std::ffi::OsString>,
    }

    #[cfg(unix)]
    impl Drop for FakeSshGuard {
        fn drop(&mut self) {
            unsafe {
                match self.original_path.take() {
                    Some(path) => std::env::set_var("PATH", path),
                    None => std::env::remove_var("PATH"),
                }
                match self.original_log.take() {
                    Some(log) => std::env::set_var("OTA_SSH_LOG", log),
                    None => std::env::remove_var("OTA_SSH_LOG"),
                }
            }
        }
    }

    #[cfg(unix)]
    fn setup_fake_ssh(root: &std::path::Path) -> FakeSshGuard {
        let bin_dir = root.join("bin");
        fs::create_dir_all(&bin_dir).unwrap();
        let ssh_path = bin_dir.join("ssh");
        install_fake_ssh(&ssh_path);
        {
            use std::os::unix::fs::PermissionsExt;
            let mut permissions = fs::metadata(&ssh_path).unwrap().permissions();
            permissions.set_mode(0o755);
            fs::set_permissions(&ssh_path, permissions).unwrap();
        }

        let log_path = root.join("ssh-log.txt");
        let original_path = std::env::var_os("PATH");
        let original_log = std::env::var_os("OTA_SSH_LOG");
        let mut path_entries = vec![bin_dir];
        if let Some(existing) = original_path.as_ref() {
            path_entries.extend(std::env::split_paths(existing));
        }
        let joined_path = std::env::join_paths(path_entries).unwrap();
        unsafe {
            std::env::set_var("PATH", &joined_path);
            std::env::set_var("OTA_SSH_LOG", &log_path);
        }

        FakeSshGuard {
            original_path,
            original_log,
        }
    }

    #[cfg(unix)]
    fn install_fake_tsh(path: &std::path::Path) {
        fs::write(
            path,
            r#"#!/bin/sh
[ "$1" = "ssh" ] || exit 1
shift
target="$1"
shift
[ "$1" = "--" ] || exit 1
shift
[ "$1" = "sh" ] || exit 1
shift
[ "$1" = "-lc" ] || exit 1
shift
printf "exec %s\n" "$target" >> "$OTA_TSH_LOG"
exec /bin/sh -lc "$1"
"#,
        )
        .unwrap();
    }

    #[cfg(unix)]
    fn install_fake_kubectl(path: &std::path::Path) {
        fs::write(
            path,
            r#"#!/bin/sh
[ "$1" = "exec" ] || exit 1
shift
target="$1"
shift
[ "$1" = "--" ] || exit 1
shift
[ "$1" = "sh" ] || exit 1
shift
[ "$1" = "-lc" ] || exit 1
shift
printf "exec %s\n" "$target" >> "$OTA_KUBECTL_LOG"
exec /bin/sh -lc "$1"
"#,
        )
        .unwrap();
    }

    fn compact_path(path: &std::path::Path, _fallback: &str) -> String {
        std::fs::canonicalize(path)
            .unwrap_or_else(|_| path.to_path_buf())
            .display()
            .to_string()
    }

    fn compact_contract(path: &std::path::Path) -> String {
        std::fs::canonicalize(path)
            .unwrap_or_else(|_| path.to_path_buf())
            .display()
            .to_string()
    }

    fn compact_workspace(path: &std::path::Path) -> String {
        std::fs::canonicalize(path)
            .unwrap_or_else(|_| path.to_path_buf())
            .display()
            .to_string()
    }

    fn strip_ansi(value: &str) -> String {
        let mut out = String::with_capacity(value.len());
        let mut chars = value.chars().peekable();
        while let Some(ch) = chars.next() {
            if ch == '\u{1b}' && chars.peek() == Some(&'[') {
                let _ = chars.next();
                for c in chars.by_ref() {
                    if c.is_ascii_alphabetic() {
                        break;
                    }
                }
                continue;
            }
            out.push(ch);
        }
        out
    }

    fn normalize_inline_whitespace(value: &str) -> String {
        value.split_whitespace().collect::<Vec<_>>().join(" ")
    }

    fn normalize_snapshot_text(value: &str) -> String {
        value.replace("\r\n", "\n").trim_end().to_string()
    }

    fn normalize_snapshot_dynamic_fields(name: &str, value: &str) -> String {
        let mut normalized = value.to_string();
        if matches!(name, "doctor_premium.txt" | "doctor_plain_premium.txt") {
            normalized = normalized.replace(
                "`./bin/node` with\n     `node --version`",
                "`./bin/node` with `node --version`",
            );
        }

        if name == "explain_narrow_premium.txt" {
            normalized = normalized.replace(
                "    » ota probed\n      `./bin/node`\n      with `node --version`",
                "    » ota probed `./bin/node` with\n      `node --version`",
            );
        }

        if name != "help_root.txt" {
            return normalized;
        }

        normalized
            .lines()
            .enumerate()
            .map(|(index, line)| {
                if index == 0 && line.starts_with("🦦 ota v") {
                    String::from("🦦 ota v<VERSION>")
                } else {
                    line.to_string()
                }
            })
            .collect::<Vec<_>>()
            .join("\n")
    }

    fn snapshot_file(name: &str) -> PathBuf {
        PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("tests")
            .join("snapshots")
            .join(name)
    }

    fn prepend_path(bin_dir: &Path) -> OsString {
        let mut entries = vec![bin_dir.to_path_buf()];
        if let Some(value) = std::env::var_os("PATH") {
            entries.extend(std::env::split_paths(&value));
        }
        std::env::join_paths(entries).expect("join PATH")
    }

    fn assert_text_snapshot(name: &str, actual: &str) {
        let normalized = normalize_snapshot_dynamic_fields(name, &normalize_snapshot_text(actual));
        if should_update_snapshots() {
            fs::write(snapshot_file(name), &normalized).expect("write snapshot");
            return;
        }
        let expected = fs::read_to_string(snapshot_file(name)).expect("read snapshot");
        let expected = normalize_snapshot_dynamic_fields(name, &normalize_snapshot_text(&expected));
        assert_eq!(normalized, expected);
    }

    fn assert_text_snapshot_for_dir(name: &str, actual: &str, dir: &std::path::Path) {
        let raw_dir = dir.display().to_string();
        let canonical_dir = fs::canonicalize(dir)
            .map(|value| value.display().to_string())
            .unwrap_or_else(|_| raw_dir.clone());
        let temp_name = dir
            .file_name()
            .map(|value| value.to_string_lossy().to_string());
        let normalized = normalize_snapshot_text(actual)
            .replace(&canonical_dir, "<TMP>")
            .replace(&raw_dir, "<TMP>");
        let normalized = temp_name
            .as_deref()
            .map(|name| normalized.replace(name, "<TMP>"))
            .unwrap_or(normalized)
            .replace("../<TMP>", "<TMP>")
            .replace("./<TMP>", "<TMP>");
        if should_update_snapshots() {
            fs::write(snapshot_file(name), &normalized).expect("write snapshot");
            return;
        }
        let expected = fs::read_to_string(snapshot_file(name)).expect("read snapshot");
        assert_eq!(normalized, normalize_snapshot_text(&expected));
    }

    fn should_update_snapshots() -> bool {
        let Ok(value) = std::env::var("OTA_UPDATE_SNAPSHOTS") else {
            return false;
        };
        matches!(
            value.trim().to_ascii_lowercase().as_str(),
            "1" | "true" | "yes" | "on"
        )
    }

