    #[test]
    fn tasks_json_reports_multiple_monorepo_members_in_order() {
        let fixture = ContractFixture::new_dir();
        fixture.write(
            "ota.yaml",
            r#"
version: 1
project:
  name: ota-monorepo
workspace:
  type: monorepo
  members:
    - api
    - web
tasks:
  setup:
    run: printf root
"#,
        );
        fixture.write(
            "api/ota.yaml",
            r#"
project:
  name: api
tasks:
  test:
    run: printf api
"#,
        );
        fixture.write(
            "web/ota.yaml",
            r#"
project:
  name: web
tasks:
  lint:
    run: 'true'
"#,
        );

        let output = run_with([
            "ota",
            "tasks",
            "--member",
            "api",
            "--member",
            "web",
            "--json",
            fixture.path(),
        ]);

        assert_eq!(output.exit_code, 0);
        let json: Value = serde_json::from_str(&output.stdout).unwrap();
        let members = json["members"].as_array().unwrap();
        assert_eq!(members[0]["member"], "api");
        assert_eq!(members[1]["member"], "web");
        assert!(
            members[0]["tasks"]
                .as_array()
                .unwrap()
                .iter()
                .any(|task| task["name"] == "test")
        );
        assert!(
            members[1]["tasks"]
                .as_array()
                .unwrap()
                .iter()
                .any(|task| task["name"] == "lint")
        );
        assert!(json["tasks"].as_array().unwrap().is_empty());
    }

