    #[test]
    fn receipt_json_archive_can_promote_baseline() {
        let fixture = ContractFixture::new(
            r#"
version: 1
project:
  name: receipt-demo
tasks:
  setup:
    run: echo ready
"#,
        );

        let output = run_with([
            "ota",
            "receipt",
            "--json",
            "--archive",
            "--promote-baseline",
            fixture.path(),
        ]);

        assert_eq!(output.exit_code, 0);
        let json: Value = serde_json::from_str(&output.stdout).unwrap();
        let archive_path = json["archive_path"].as_str().unwrap();
        let promoted = &json["promoted_baseline"];
        assert_eq!(promoted["archive_path"], archive_path);
        assert!(
            promoted["path"]
                .as_str()
                .unwrap()
                .ends_with(".ota/receipts/repo-baseline.json")
        );
        assert!(Path::new(promoted["path"].as_str().unwrap()).is_file());
        let pointer: Value =
            serde_json::from_str(&fs::read_to_string(promoted["path"].as_str().unwrap()).unwrap())
                .unwrap();
        assert_eq!(pointer["kind"], "repo_receipt_baseline");
        assert_eq!(pointer["contract_identity"], "ota.yaml");
        assert_eq!(
            pointer["archive_file"],
            Path::new(archive_path)
                .file_name()
                .unwrap()
                .to_string_lossy()
                .to_string()
        );
    }

    #[test]
    fn receipt_json_diff_against_latest_archive_classifies_changes() {
        let _guard = env_mutex_lock();
        let fixture = ContractFixture::new(
            r#"
version: 1
project:
  name: receipt-diff
env:
  vars:
    OTA_BASELINE_REQUIRED:
      required: true
"#,
        );

        let current = run_with(["ota", "receipt", "--json", fixture.path()]);
        assert_eq!(current.exit_code, 1);
        let current_json: Value = serde_json::from_str(&current.stdout).unwrap();
        let unchanged = current_json["findings"]
            .as_array()
            .unwrap()
            .iter()
            .find(|finding| finding["summary"] == "No tasks defined in contract")
            .cloned()
            .unwrap();

        let baseline_payload = serde_json::json!({
            "ok": false,
            "path": fixture.file_path().display().to_string(),
            "mode": "receipt",
            "summary": {
                "error_count": 2,
                "warn_count": 0,
                "info_count": 0,
                "step_count": 1
            },
            "receipt": {
                "ok": false,
                "path": fixture.file_path().display().to_string(),
                "scope": "repo",
                "contract": fixture.file_path().display().to_string(),
                "backend": "native",
                "summary": {
                    "error_count": 2,
                    "warn_count": 0,
                    "info_count": 0,
                    "step_count": 1
                },
                "steps": [
                    {
                        "order": 1,
                        "label": "readiness",
                        "status": "NOT READY"
                    }
                ]
            },
            "findings": [
                unchanged,
                {
                    "severity": "error",
                    "summary": "Missing tool: old-tool",
                    "why": "the contract requires `old-tool`, but ota could not find it on PATH",
                    "next": "install `old-tool` and make it available on PATH, then rerun `ota doctor`"
                }
            ]
        });
        fixture.write(
            ".ota/receipts/repo-receipt-20260412-101010-123Z.json",
            &serde_json::to_string_pretty(&baseline_payload).unwrap(),
        );

        let output = run_with([
            "ota",
            "receipt",
            "--json",
            "--baseline",
            "latest",
            fixture.path(),
        ]);

        assert_eq!(output.exit_code, 0);
        let json: Value = serde_json::from_str(&output.stdout).unwrap();
        assert_eq!(json["ok"], false);
        assert_eq!(json["mode"], "diff");
        assert_eq!(json["baseline"]["source"], "latest");
        assert_eq!(json["summary"]["introduced"]["count"], 1);
        assert_eq!(json["summary"]["resolved"]["count"], 1);
        assert_eq!(json["summary"]["unchanged"]["count"], 1);
        assert_eq!(
            json["introduced"][0]["summary"],
            "Missing environment variable: OTA_BASELINE_REQUIRED"
        );
        assert_eq!(json["resolved"][0]["summary"], "Missing tool: old-tool");
        assert_eq!(
            json["unchanged"][0]["summary"],
            "No tasks defined in contract"
        );
    }

