    #[test]
    fn shared_commands_report_multiple_primary_listener_conflicts() {
        let _guard = env_mutex_lock();
        let fixture = ContractFixture::new(
            r#"
version: 1
project:
  name: ota
execution:
  default_context: app
  contexts:
    app:
      backend: container
      lifecycle: persistent
      container:
        image: ghcr.io/ota/dev:latest
tasks:
  dev:
    context: app
    run: printf ready
    runtime:
      kind: service
      listeners:
        http:
          protocol: http
          bind:
            address: 0.0.0.0
            port:
              mode: fixed
              value: 3000
          project:
            host:
              address: 127.0.0.1
              primary: true
              port:
                mode: auto
        metrics:
          protocol: http
          bind:
            address: 0.0.0.0
            port:
              mode: fixed
              value: 9090
          project:
            host:
              address: 127.0.0.1
              primary: true
              port:
                mode: auto
"#,
        );

        let cases = [
            ("validate", "ota validate"),
            ("doctor", "ota doctor"),
            ("receipt", "ota receipt"),
            ("explain", "ota explain"),
        ];
        for (command, rerun_command) in cases {
            let output = run_with(["ota", command, fixture.path()]);
            assert_eq!(output.exit_code, 1, "command `{command}` should fail");
            let stderr = strip_ansi(output.stderr.as_deref().unwrap_or_default());
            assert!(stderr.contains("Invalid contract"), "command `{command}`");
            assert!(
                stderr.contains("Field: tasks.dev.runtime.listeners"),
                "command `{command}`"
            );
            assert!(
                stderr.contains(
                    "task `dev` marks multiple projected listeners as primary (`http`, `metrics`)"
                ),
                "command `{command}`"
            );
            assert!(
                stderr.contains("keep `project.host.primary: true` on one projected listener only"),
                "command `{command}`"
            );
            assert!(
                stderr.contains(&format!("rerun `{rerun_command} ")),
                "command `{command}`"
            );
        }
    }

