    #[test]
    fn run_failure_try_footer_stays_tight_before_run_summary() {
        let _guard = env_mutex_lock();
        let fixture = ContractFixture::new(
            r#"
version: 1
project:
  name: ota
execution:
  default_context: app
  contexts:
    app:
      backend: native
tasks:
  fail:
    context: app
    run: exit 7
"#,
        );

        let output = run_with(["ota", "run", "fail", fixture.path()]);

        assert_eq!(output.exit_code, 7);
        let stderr = strip_ansi(output.stderr.as_deref().unwrap_or_default());
        assert!(stderr.contains("Task Failed"));
        assert!(stderr.contains("`fail` exited with code 7"));
        assert!(stderr.contains("Why: task `fail` returned a non-zero exit code"));
        assert!(stderr.contains("Next:"));
        assert!(stderr.contains("ota tasks --use"));
        assert!(stderr.contains(fixture.path()));
        assert!(stderr.contains("Context: app\nWhere:"));
        assert!(stderr.contains("Why: task `fail` returned a non-zero exit code\n"));
        assert!(
            stderr.contains("Why: task `fail` returned a non-zero exit code\n\n🦦 RUN SUMMARY")
        );
        assert!(!stderr.contains("Why: task `fail` returned a non-zero exit code\n\nNext:"));
        assert!(!stderr.contains("Next:\n\n\nRUN SUMMARY"));
    }

    #[cfg(unix)]
    #[test]
    fn run_failure_names_failed_depends_on_task() {
        let _guard = env_mutex_lock();
        let fixture = ContractFixture::new(
            r#"
version: 1
project:
  name: ota
execution:
  default_context: app
  contexts:
    app:
      backend: native
tasks:
  typecheck:
    context: app
    run: exit 9
  build:
    context: app
    depends_on:
      - typecheck
    run: echo build
"#,
        );

        let output = run_with(["ota", "run", "build", fixture.path()]);

        assert_eq!(output.exit_code, 9);
        let stderr = strip_ansi(output.stderr.as_deref().unwrap_or_default());
        assert!(stderr.contains("Task Failed"), "{stderr}");
        assert!(stderr.contains("Requested: build"), "{stderr}");
        assert!(stderr.contains("Failed Step: typecheck"), "{stderr}");
        assert!(
            stderr.contains(
                "requested task `build` failed because depends_on task `typecheck` returned a non-zero exit code"
            ),
            "{stderr}"
        );
        assert!(
            stderr.contains(
                "running on the host environment; depends_on task `typecheck` failed for requested task `build`"
            ),
            "{stderr}"
        );
    }

    #[cfg(unix)]
    #[test]
    fn run_failure_reports_host_publication_conflict_as_a_host_port_error() {
        let _guard = env_mutex_lock();
        let listener = std::net::TcpListener::bind(("127.0.0.1", 0))
            .expect("bind test port for host publication conflict");
        let host_port = listener
            .local_addr()
            .expect("read local host publication port")
            .port();
        let fixture_text = format!(
            r#"
version: 1
project:
  name: ota
execution:
  default_context: app
  contexts:
    app:
      backend: container
      lifecycle: ephemeral
      container:
        image: node:24-bookworm
tasks:
  setup:
    context: app
    run: echo setup
  dev:
    context: app
    depends_on:
      - setup
    run: echo dev
    runtime:
      kind: service
      listeners:
        http:
          protocol: http
          bind:
            address: 0.0.0.0
            port:
              mode: fixed
              value: {host_port}
          project:
            host:
              address: 127.0.0.1
              port:
                mode: fixed
                value: {host_port}
              path: /
"#
        );
        let fixture = ContractFixture::new(&fixture_text);

        let bin_dir = fixture.dir.path().join("bin");
        fs::create_dir_all(&bin_dir).expect("create bin dir");
        install_fake_docker(&bin_dir.join("docker"));
        let path = prepend_path(&bin_dir);
        let _path_guard = EnvVarGuard::set("PATH", path);
        let _cwd = CurrentDirGuard::enter(fixture.dir.path());
        let _keep_port_bound = listener;

        let output = run_with(["ota", "run", "dev", fixture.path()]);
        assert_eq!(output.exit_code, 1);
        let stderr = strip_ansi(output.stderr.as_deref().unwrap_or_default());
        assert!(stderr.contains("Host publication failed"), "{stderr}");
        assert!(stderr.contains("Field: tasks.dev.runtime.listeners.http.project.host.port"));
        assert!(!stderr.starts_with("Error response from daemon:"));
        assert!(stderr.contains(&format!(
            "host port `{host_port}` on `127.0.0.1` is already allocated"
        )));
        assert!(stderr.contains(
            "rerun `ota run dev --host-port <free port>` to publish on a different host port"
        ));
        assert!(stderr.contains(&format!(
            "stop the process or container currently using `127.0.0.1:{host_port}`"
        )));
        assert!(stderr.contains(
            "or change `tasks.dev.runtime.listeners.http.project.host.port.mode` to `auto`"
        ));
        assert!(!stderr.contains("Task Failed"));
        assert!(!fixture.dir.path().join("docker-log.txt").exists());
    }

    #[cfg(unix)]
    #[test]
    fn run_failure_with_auto_host_publication_conflict_suggests_rerun_not_mode_change() {
        use std::os::unix::fs::PermissionsExt;

        let _guard = env_mutex_lock();
        let fixture = ContractFixture::new(
            r#"
version: 1
project:
  name: ota
execution:
  default_context: app
  contexts:
    app:
      backend: container
      lifecycle: ephemeral
      container:
        image: node:24-bookworm
tasks:
  dev:
    context: app
    run: echo dev
    runtime:
      kind: service
      listeners:
        http:
          protocol: http
          bind:
            address: 0.0.0.0
            port:
              mode: fixed
              value: 3000
          project:
            host:
              address: 127.0.0.1
              port:
                mode: fixed
                value: 3001
              path: /
"#,
        );

        let bin_dir = fixture.dir.path().join("bin");
        fs::create_dir_all(&bin_dir).expect("create bin dir");
        let docker_real = bin_dir.join("docker-real");
        install_fake_docker(&docker_real);
        let mut real_permissions = fs::metadata(&docker_real).unwrap().permissions();
        real_permissions.set_mode(0o755);
        fs::set_permissions(&docker_real, real_permissions).unwrap();
        let docker_wrapper = bin_dir.join("docker");
        fs::write(
            &docker_wrapper,
            r#"#!/bin/sh
if [ "$1" = "create" ] || [ "$1" = "run" ]; then
  printf "Bind for 127.0.0.1:3000 failed: port is already allocated\n" >&2
  exit 1
fi
exec "$(dirname "$0")/docker-real" "$@"
"#,
        )
        .unwrap();
        let mut wrapper_permissions = fs::metadata(&docker_wrapper).unwrap().permissions();
        wrapper_permissions.set_mode(0o755);
        fs::set_permissions(&docker_wrapper, wrapper_permissions).unwrap();

        let path = prepend_path(&bin_dir);
        let _path_guard = EnvVarGuard::set("PATH", path);
        let _cwd = CurrentDirGuard::enter(fixture.dir.path());

        let output = run_with(["ota", "run", "dev", fixture.path()]);

        assert_eq!(output.exit_code, 1);
        let stderr = strip_ansi(output.stderr.as_deref().unwrap_or_default());
        assert!(stderr.contains("Host publication failed"), "{stderr}");
        assert!(stderr.contains("rerun `ota run dev --host-port <free port>`"));
        assert!(!stderr.contains(
            "change `tasks.dev.runtime.listeners.http.project.host.port.mode` to `auto`"
        ));
    }

    #[cfg(unix)]
    #[test]
    fn run_failure_reports_reused_persistent_container_listener_bind_conflict() {
        use std::os::unix::fs::PermissionsExt;

        let _guard = env_mutex_lock();
        let fixture = ContractFixture::new(
            r#"
version: 1
project:
  name: ota
execution:
  preferred: container
  lifecycle: persistent
  backends:
    container:
      image: node:24-bookworm
tasks:
  dev:
    run: echo dev
    runtime:
      kind: service
      listeners:
        http:
          protocol: http
          bind:
            address: 0.0.0.0
            port:
              mode: fixed
              value: 8080
          project:
            host:
              address: 127.0.0.1
              port:
                mode: auto
              path: /
"#,
        );

        let bin_dir = fixture.dir.path().join("bin");
        fs::create_dir_all(&bin_dir).expect("create bin dir");
        let docker_path = bin_dir.join("docker");
        install_fake_docker(&docker_path);
        let mut permissions = fs::metadata(&docker_path).unwrap().permissions();
        permissions.set_mode(0o755);
        fs::set_permissions(&docker_path, permissions).unwrap();

        let path = prepend_path(&bin_dir);
        let _path_guard = EnvVarGuard::set("PATH", path);
        let _cwd = CurrentDirGuard::enter(fixture.dir.path());

        let first = run_with(["ota", "run", "dev", fixture.path()]);
        assert_eq!(first.exit_code, 1);
        let first_stderr = strip_ansi(first.stderr.as_deref().unwrap_or_default());
        assert!(
            first_stderr.contains("Service failed to start"),
            "{first_stderr}"
        );

        let state_dir = bin_dir.join("docker-state");
        let container_name = fs::read_dir(&state_dir)
            .expect("read docker state dir")
            .filter_map(|entry| entry.ok())
            .find_map(|entry| {
                let name = entry.file_name();
                let name = name.to_str()?;
                name.strip_suffix(".path").map(str::to_string)
            })
            .expect("persistent container name");
        fs::write(
            state_dir.join(format!("{container_name}.proc-net")),
            "  sl  local_address rem_address   st tx_queue rx_queue tr tm->when retrnsmt   uid  timeout inode\n   0: 00000000:1F90 00000000:0000 0A 00000000:00000000 00:00000000 00000000     0        0 0 1 0000000000000000 100 0 0 10 0\n",
        )
        .expect("write fake proc net");

        let second = run_with(["ota", "run", "dev", fixture.path()]);

        assert_eq!(second.exit_code, 1);
        let stderr = strip_ansi(second.stderr.as_deref().unwrap_or_default());
        assert!(stderr.contains("Listener bind conflict"), "{stderr}");
        assert!(stderr.contains("Field: tasks.dev.runtime.listeners.http.bind.port"));
        assert!(stderr.contains(&format!(
            "persistent container `{container_name}` is being reused"
        )));
        assert!(
            stderr
                .contains("task `dev` listener `http` needs `0.0.0.0:8080` inside that container")
        );
        assert!(stderr.contains("port `8080` is already in use in the reused container"));
        assert!(stderr.contains("or run `ota clean` to recreate the persistent backend"));
        assert!(!stderr.contains("Task Failed"));
    }

