    #[test]
    fn appends_update_notice_to_successful_output() {
        let (tx, rx) = mpsc::channel();
        tx.send(Some(String::from(
            "A newer `\u{1b}[38;5;130mota\u{1b}[39m` release is available: \u{1b}[92mv9.9.9\u{1b}[39m\nRun `\u{1b}[38;5;130mota self-update\u{1b}[39m` or `\u{1b}[38;5;130mota upgrade\u{1b}[39m` to update.",
        )))
        .unwrap();

        let output =
            maybe_append_update_notice(CommandOutput::success(String::from("ok")), Some(rx));

        assert_eq!(output.stdout, "ok");
        assert_eq!(
            output.stderr,
            Some(String::from(
                "\n\x1b[1mA newer `\x1b[38;5;130mota\x1b[39m` release is available: \x1b[92mv9.9.9\x1b[39m\nRun `\x1b[38;5;130mota self-update\x1b[39m` or `\x1b[38;5;130mota upgrade\x1b[39m` to update.\x1b[0m"
            ))
        );
    }

    #[test]
    fn appends_background_update_notice_with_explicit_long_timeout() {
        let (tx, rx) = mpsc::channel();
        let delay = Duration::from_millis(1250);
        thread::spawn(move || {
            thread::sleep(delay);
            let _ = tx.send(Some(String::from("notice")));
        });

        let output = maybe_append_update_notice_with_timeout(
            CommandOutput::success(String::from("ok")),
            Some(rx),
            Duration::from_millis(3000),
        );

        assert_eq!(output.stdout, "ok");
        assert_eq!(output.stderr, Some(String::from("\n\x1b[1mnotice\x1b[0m")));
    }

    #[test]
    fn wait_budget_stays_small_on_all_platforms() {
        assert!(update_notice_wait_timeout() <= Duration::from_millis(50));
    }

    #[test]
    fn does_not_wait_for_slow_windows_background_update_notice() {
        let (tx, rx) = mpsc::channel();
        let delay = Duration::from_millis(1250);
        thread::spawn(move || {
            thread::sleep(delay);
            let _ = tx.send(Some(String::from("notice")));
        });

        let output = maybe_append_update_notice_with_timeout(
            CommandOutput::success(String::from("ok")),
            Some(rx),
            update_notice_wait_timeout(),
        );

        assert_eq!(output.stdout, "ok");
        assert_eq!(output.stderr, None);
    }

