    #[test]
    fn doctor_json_reports_all_suspicious_remote_target_warnings_together() {
        let fixture = ContractFixture::new_dir();
        fixture.write(
            "ota.yaml",
            r#"
version: 1
project:
  name: ota-monorepo
workspace:
  type: monorepo
  members:
    - ssh-member
    - tsh-member
    - kubectl-member
"#,
        );
        fixture.write(
            "ssh-member/ota.yaml",
            r#"
project:
  name: ssh-member
execution:
  preferred: remote
  backends:
    remote:
      provider: ssh
      target: sandbox-dev
tasks:
  test:
    run: cargo test
"#,
        );
        fixture.write(
            "tsh-member/ota.yaml",
            r#"
project:
  name: tsh-member
execution:
  preferred: remote
  backends:
    remote:
      provider: tsh
      target: sandbox-dev
tasks:
  test:
    run: cargo test
"#,
        );
        fixture.write(
            "kubectl-member/ota.yaml",
            r#"
project:
  name: kubectl-member
execution:
  preferred: remote
  backends:
    remote:
      provider: kubectl
      target: ota-dev
tasks:
  test:
    run: cargo test
"#,
        );

        let output = run_with(["ota", "doctor", "--json", fixture.path()]);
        let json: Value = serde_json::from_str(&output.stdout).unwrap();
        let members = json["members"].as_array().unwrap();
        assert_eq!(members.len(), 3);
        let summaries = members
            .iter()
            .flat_map(|member| member["findings"].as_array().into_iter().flatten())
            .map(|finding| finding["summary"].as_str().unwrap_or_default().to_string())
            .collect::<Vec<_>>();
        assert!(
            summaries
                .iter()
                .any(|summary| summary == "Suspicious remote target for ssh: sandbox-dev")
        );
        assert!(
            summaries
                .iter()
                .any(|summary| summary == "Suspicious remote target for tsh: sandbox-dev")
        );
        assert!(
            summaries
                .iter()
                .any(|summary| summary == "Suspicious remote target for kubectl: ota-dev")
        );
    }

