    #[test]
    fn agents_write_preserves_existing_content_and_appends_generated_block() {
        let fixture = ContractFixture::new(
            r#"
version: 1
project:
  name: ota
agent:
  entrypoint: setup
tasks:
  setup:
    run: echo setup
"#,
        );
        let agents_path = fixture.dir.path().join("AGENTS.md");
        fs::write(&agents_path, "Custom guidance\n").unwrap();

        let output = run_with(["ota", "agents", "--write", fixture.path()]);

        assert_eq!(output.exit_code, 0);
        let stdout = strip_ansi(&output.stdout);
        assert!(stdout.contains("AGENTS"));
        let agents_md = fs::read_to_string(&agents_path).unwrap();
        assert!(agents_md.starts_with("Custom guidance"));
        assert!(agents_md.contains("ota-generated-agent-guidance:start"));
        assert!(agents_md.contains("# AGENTS.md"));
        assert!(agents_md.contains("Generated from `./ota.yaml` by `ota agents`."));
        assert!(!agents_md.contains("DO NOT ALTER OR REMOVE COPYRIGHT NOTICES"));
        assert!(agents_md.contains("`entrypoint`: `setup` (`ota run setup`)"));
    }

    #[test]
    fn agents_write_skips_duplicate_generated_content() {
        let fixture = ContractFixture::new(
            r#"
version: 1
project:
  name: ota
agent:
  entrypoint: setup
  default_task: ci
tasks:
  setup:
    run: echo setup
  ci:
    run: echo ci
"#,
        );

        let preview = run_with(["ota", "agents", "--json", fixture.path()]);
        let json: Value = serde_json::from_str(&preview.stdout).unwrap();
        let generated = json["content"].as_str().unwrap();
        let agents_path = fixture.dir.path().join("AGENTS.md");
        let original = format!("Custom guidance\n\n{generated}");
        fs::write(&agents_path, &original).unwrap();

        let output = run_with(["ota", "agents", "--write", fixture.path()]);

        assert_eq!(output.exit_code, 0);
        let stdout = strip_ansi(&output.stdout);
        assert!(stdout.contains("already in sync"));
        assert_eq!(fs::read_to_string(&agents_path).unwrap(), original);

        let json_output = run_with(["ota", "agents", "--write", "--json", fixture.path()]);
        let json: Value = serde_json::from_str(&json_output.stdout).unwrap();
        assert_eq!(json["mode"], "already_in_sync");
        assert_eq!(json["written"], false);
    }

    #[test]
    fn agents_rejects_org_policy_pack_target_with_wrong_target_message() {
        let fixture = TempDir::new().unwrap();
        fs::write(
            fixture.path().join("ota.yaml"),
            r#"
version: 1
project:
  name: ota
"#,
        )
        .unwrap();
        fs::create_dir_all(fixture.path().join(".ota")).unwrap();
        let policy_path = fixture.path().join(".ota").join("org-policy.yaml");
        fs::write(&policy_path, "policies: {}\n").unwrap();

        let output = run_with(["ota", "agents", policy_path.to_str().unwrap()]);

        assert_eq!(output.exit_code, 1);
        let stdout = strip_ansi(&output.stdout);
        assert!(stdout.contains("Wrong command target"));
        assert!(stdout.contains("is an org policy pack, not a repo contract"));
        assert!(stdout.contains("`ota agents` reads repo contracts such as `ota.yaml`"));
        assert!(stdout.contains("ota policy"));
        assert!(stdout.contains("ota agents"));
        assert!(!stdout.contains("Operation failed"));
        assert!(!stdout.contains("INVALID ota.yaml"));
        assert!(!stdout.contains("ota init"));
    }

    #[test]
    fn agents_renders_structured_invalid_contract_for_repo_local_policy_pack_fields() {
        let fixture = TempDir::new().unwrap();
        fs::write(
            fixture.path().join("ota.yaml"),
            r#"
version: 1
project:
  name: ota
policies:
  version_policy:
    runtimes:
      node:
        approved_versions:
          - "22"
  provisioning:
    node:
      source: brew
      approved_versions:
        - "22"
  adapter_bootstrap:
    brew:
      source: brew-bootstrap
      approved_versions:
        - "4"
"#,
        )
        .unwrap();

        let output = run_with(["ota", "agents", fixture.path().to_str().unwrap()]);

        assert_eq!(output.exit_code, 1);
        let stdout = strip_ansi(&output.stdout);
        assert!(stdout.contains("Invalid contract"));
        assert!(stdout.contains("repo contracts must not declare `policies.version_policy`"));
        assert!(stdout.contains("repo contracts must not declare `policies.provisioning`"));
        assert!(stdout.contains("repo contracts must not declare `policies.adapter_bootstrap`"));
        assert!(stdout.contains("rerun `ota validate"));
        assert!(stdout.contains("rerun `ota agents"));
        assert!(!stdout.contains("Operation failed"));
        assert!(!stdout.contains("INVALID ota.yaml"));
        assert!(!stdout.contains("ota init"));
    }

