    #[test]
    fn init_packs_text_aligns_wrapped_values_under_labels() {
        let _guard = env_mutex_lock();
        let original_columns = std::env::var_os("COLUMNS");
        unsafe {
            std::env::set_var("COLUMNS", "96");
        }

        let output = run_with(["ota", "init", "--packs"]);

        unsafe {
            match original_columns {
                Some(value) => std::env::set_var("COLUMNS", value),
                None => std::env::remove_var("COLUMNS"),
            }
        }

        assert_eq!(output.exit_code, 0);
        let stripped = strip_ansi(&output.stdout);
        let lines = stripped.lines().collect::<Vec<_>>();
        let notes_index = lines
            .iter()
            .position(|line| {
                line.contains("Notes: Use this when the repo is intentionally Maven-based")
            })
            .expect("wrapped Maven notes line");
        let continuation = lines[notes_index + 1];
        assert!(!continuation.trim_start().starts_with("Notes:"));
        assert_eq!(continuation.chars().take_while(|ch| *ch == ' ').count(), 9);
    }

    #[test]
    fn init_packs_text_does_not_pre_wrap_when_columns_is_unknown() {
        let _guard = env_mutex_lock();
        let original_columns = std::env::var_os("COLUMNS");
        unsafe {
            std::env::remove_var("COLUMNS");
        }

        let output = run_with(["ota", "init", "--packs"]);

        unsafe {
            match original_columns {
                Some(value) => std::env::set_var("COLUMNS", value),
                None => std::env::remove_var("COLUMNS"),
            }
        }

        assert_eq!(output.exit_code, 0);
        let stdout = strip_ansi(&output.stdout);
        assert!(stdout.contains(
            "Description: Conventional Java starter for Maven-driven repos with build and test lifecycles, preferring `mvnw` when the repo already ships it."
        ));
        assert!(stdout.contains(
            "Notes: Use this when the repo is intentionally Maven-based and you want an explicit Java starter without relying on repo detection. If `mvnw` already exists, ota uses the wrapper instead of requiring a global Maven install."
        ));
    }

    #[test]
    fn init_packs_json_reports_catalog_metadata() {
        let output = run_with(["ota", "init", "--packs", "--json"]);

        assert_eq!(output.exit_code, 0);
        let json: Value = serde_json::from_str(&output.stdout).unwrap();
        assert_eq!(json["ok"], true);
        assert_eq!(json["mode"], "catalog");
        let packs = json["packs"].as_array().expect("packs array");
        assert!(packs.iter().any(|entry| entry["name"] == "node"));
        assert!(packs.iter().any(|entry| entry["name"] == "python"));
        let go = packs
            .iter()
            .find(|entry| entry["name"] == "go")
            .expect("go pack");
        assert_eq!(go["command"], "ota init --pack go");
        assert_eq!(go["next"], "ota init --pack go --dry-run .");
        assert_eq!(go["seeds"]["tasks"][1], "build");
        assert!(go["options"].is_null());
        let node = packs
            .iter()
            .find(|entry| entry["name"] == "node")
            .expect("node pack");
        assert_eq!(node["options"][0]["flag"], "--package-manager");
        assert_eq!(node["options"][0]["default"], "pnpm");
        assert_eq!(
            node["options"][0]["values"],
            json!(["npm", "pnpm", "yarn", "bun"])
        );
        assert!(
            node["does_not_infer"]
                .as_array()
                .expect("node does_not_infer")
                .iter()
                .any(|entry| entry
                    .as_str()
                    .is_some_and(|value| value.contains(".env.local") && value.contains(".env")))
        );
        let python = packs
            .iter()
            .find(|entry| entry["name"] == "python")
            .expect("python pack");
        assert_eq!(python["options"][0]["flag"], "--test-runner");
        assert_eq!(python["options"][0]["default"], "pytest");
        let rust = packs
            .iter()
            .find(|entry| entry["name"] == "rust")
            .expect("rust pack");
        assert_eq!(rust["seeds"]["tools"][0], "cargo");
        assert_eq!(
            rust["does_not_infer"][0],
            "workspace members, feature flags, or custom cargo aliases beyond the standard fetch/build/test loop"
        );
        let dotnet = packs
            .iter()
            .find(|entry| entry["name"] == "dotnet")
            .expect("dotnet pack");
        assert_eq!(dotnet["command"], "ota init --pack dotnet");
        assert_eq!(dotnet["next"], "ota init --pack dotnet --dry-run .");
        assert_eq!(dotnet["seeds"]["runtimes"][0], "dotnet");
        assert_eq!(dotnet["seeds"]["tools"][0], "dotnet");
        assert_eq!(dotnet["seeds"]["checks"][0], "dotnet-installed");
        assert_eq!(dotnet["seeds"]["tasks"][2], "test");
        assert!(
            dotnet["does_not_infer"][0]
                .as_str()
                .expect("dotnet does_not_infer")
                .contains("solution-specific target selection")
        );
        let php_composer = packs
            .iter()
            .find(|entry| entry["name"] == "php-composer")
            .expect("php-composer pack");
        assert_eq!(php_composer["command"], "ota init --pack php-composer");
        assert_eq!(
            php_composer["next"],
            "ota init --pack php-composer --dry-run ."
        );
        assert_eq!(php_composer["seeds"]["runtimes"][0], "php");
        assert_eq!(php_composer["seeds"]["tools"][0], "composer");
        assert_eq!(php_composer["seeds"]["checks"][1], "composer-installed");
        assert_eq!(php_composer["seeds"]["tasks"][0], "setup");
        assert!(
            php_composer["does_not_infer"][0]
                .as_str()
                .expect("php-composer does_not_infer")
                .contains("scripts.test")
        );
        let java_maven = packs
            .iter()
            .find(|entry| entry["name"] == "java-maven")
            .expect("java-maven pack");
        assert_eq!(java_maven["command"], "ota init --pack java-maven");
        assert_eq!(java_maven["seeds"]["tools"], json!([]));
        assert_eq!(java_maven["seeds"]["checks"][0], "java-installed");
        assert!(
            java_maven["does_not_infer"][0]
                .as_str()
                .expect("java-maven does_not_infer")
                .contains("multi-module reactor details")
        );
        let java_gradle = packs
            .iter()
            .find(|entry| entry["name"] == "java-gradle")
            .expect("java-gradle pack");
        assert_eq!(
            java_gradle["next"],
            "ota init --pack java-gradle --dry-run ."
        );
        assert_eq!(java_gradle["seeds"]["tools"], json!([]));
        assert_eq!(java_gradle["seeds"]["tasks"][0], "setup");
        assert!(
            java_gradle["does_not_infer"][0]
                .as_str()
                .expect("java-gradle does_not_infer")
                .contains("multi-project build logic")
        );
    }

