    #[test]
    fn init_pack_mismatch_surfaces_advisory_without_changing_selected_pack() {
        let fixture = ContractFixture::new_dir();
        fixture.write(
            "package.json",
            r#"{
  "name": "web",
  "packageManager": "pnpm@10.0.0",
  "scripts": {
    "dev": "pnpm dev",
    "test": "pnpm test"
  }
}"#,
        );

        let output = run_with([
            "ota",
            "init",
            "--pack",
            "python",
            "--json",
            "--dry-run",
            fixture.path(),
        ]);

        assert_eq!(output.exit_code, 0);
        let json: Value = serde_json::from_str(&output.stdout).unwrap();
        assert_eq!(json["pack"], "python");
        assert_eq!(json["config"]["runtimes"]["python"], "3.12");
        assert_eq!(
            json["pack_advisory"]["selected_pack"],
            serde_json::json!("python")
        );
        assert_eq!(
            json["pack_advisory"]["suggested_pack"],
            serde_json::json!("node")
        );
        assert_eq!(
            json["pack_advisory"]["selected_pack_score"],
            serde_json::json!(0)
        );
        assert_eq!(
            json["pack_advisory"]["suggested_pack_score"],
            serde_json::json!(3)
        );
        assert_eq!(json["pack_advisory"]["score_gap"], serde_json::json!(3));
        assert_eq!(
            json["pack_advisory"]["signals"][0],
            serde_json::json!("package.json")
        );
        assert_eq!(
            json["pack_advisory"]["signal_details"][0]["signal"],
            serde_json::json!("package.json")
        );
        assert_eq!(
            json["pack_advisory"]["signal_details"][0]["weight"],
            serde_json::json!(3)
        );
        assert!(json["pack_advisory"]["selected_signal_details"].is_null());
        assert!(
            json["pack_advisory"]["next"]
                .as_str()
                .expect("pack advisory next")
                .starts_with("ota init --pack node --dry-run")
        );
    }

