    #[cfg(unix)]
    #[test]
    fn run_reports_container_execution_banner_with_container_name() {
        use std::os::unix::fs::PermissionsExt;

        let _guard = env_mutex_lock();
        let fixture = ContractFixture::new(
            r#"
version: 1
project:
  name: ota
execution:
  preferred: container
  lifecycle: persistent
  backends:
    container:
      image: ghcr.io/ota/test:latest
tasks:
  setup:
    run: exit 0
"#,
        );
        let bin_dir = fixture.dir.path().join("bin");
        fs::create_dir_all(&bin_dir).unwrap();
        let docker_path = bin_dir.join("docker");
        install_fake_docker(&docker_path);
        let mut permissions = fs::metadata(&docker_path).unwrap().permissions();
        permissions.set_mode(0o755);
        fs::set_permissions(&docker_path, permissions).unwrap();

        let original_path = std::env::var_os("PATH");
        let mut path_entries = vec![bin_dir.clone()];
        if let Some(existing) = original_path.as_ref() {
            path_entries.extend(std::env::split_paths(existing));
        }
        let joined_path = std::env::join_paths(path_entries).unwrap();
        unsafe {
            std::env::set_var("PATH", &joined_path);
        }

        let output = run_with(["ota", "run", "setup", fixture.path()]);

        match original_path {
            Some(path) => unsafe {
                std::env::set_var("PATH", path);
            },
            None => unsafe {
                std::env::remove_var("PATH");
            },
        }

        assert_eq!(output.exit_code, 0);
        let rendered = strip_ansi(&format!(
            "{}\n{}",
            output.stdout,
            output.stderr.as_deref().unwrap_or_default()
        ));
        assert!(rendered.contains("SUMMARY"));
        assert!(rendered.contains("Mode:"));
        assert!(rendered.contains("container"));
        assert!(rendered.contains("Task:"));
        assert!(rendered.contains("setup"));
        assert!(rendered.contains("Status:"));
        assert!(rendered.contains("success"));
        assert!(rendered.contains("Container:"));
        assert!(rendered.contains("ota-"));
        assert!(rendered.contains("Lifecycle:"));
        assert!(rendered.contains("persistent"));
        assert!(rendered.contains("Note:"));
        assert!(rendered.contains("persistent container"));
        assert!(rendered.contains("Next:"));
        assert!(rendered.contains("ota tasks --use"));
    }

