    #[test]
    fn completion_command_prints_shell_setup_instructions() {
        let output = run_with(["ota", "completion", "zsh"]);

        assert_eq!(output.exit_code, 0);
        assert!(output.stdout.contains("ota completion zsh --setup"));
        assert!(output.stdout.contains("ota completion zsh --remove"));
        assert!(
            output
                .stdout
                .contains("Manual completion file (~/.config/ota/zsh/_ota):")
        );
        assert!(output.stdout.contains("#compdef ota"));
        assert!(
            output
                .stdout
                .contains("compadd -Q -V ota_primary -d primary_display -o nosort")
        );
        assert!(!output.stdout.contains("compadd -Q -X 'Suggestions'"));
        assert!(
            output
                .stdout
                .contains("compadd -Q -X 'Options' -V ota_options -d option_display -o nosort")
        );
        assert!(
            output
                .stdout
                .contains("local escaped_completion=\"${completion//\\\\:/$placeholder}\"")
        );
        assert!(output.stdout.contains("value=\"${value//$placeholder/:}\""));
        assert!(output.stdout.contains("value=\"${(Q)value}\""));
        assert!(output.stdout.contains("help=\"${(Q)help}\""));
        assert!(!output.stdout.contains("local value=\"${completion%%:*}\""));
        assert!(!output.stdout.contains("local rendered"));
        assert!(!output.stdout.contains("local desc"));
        assert!(!output.stdout.contains("_describe 'values'"));
        assert!(
            output
                .stdout
                .contains("_ota_completion_file=\"$HOME/.config/ota/zsh/_ota\"")
        );
        assert!(output.stdout.contains("_comps[ota]=_ota"));
        assert!(
            output
                .stdout
                .contains("Reload your shell after updating ota")
        );
    }

