        let xdg_config_home = dir.path().join(".config");
        let _xdg = EnvVarGuard::set(
            "XDG_CONFIG_HOME",
            xdg_config_home.as_os_str().to_os_string(),
        );
        let _shell = EnvVarGuard::set("SHELL", OsString::from("/bin/zsh"));

