    #[test]
    fn doctor_uses_asdf_tool_remediation_when_repo_signals_tool_versions() {
        let _guard = env_mutex_lock();
        let fixture = ContractFixture::new(
            r#"
version: 1
project:
  name: asdf-demo
tools:
  maven: "3.9.9"
tasks:
  ci:
    run: echo ci
"#,
        );
        fixture.write(".tool-versions", "maven 3.9.9\n");

        let bin_dir = fixture.dir.path().join("bin");
        fs::create_dir_all(&bin_dir).expect("create bin dir");
        let mvn_body = if cfg!(windows) {
            "@echo off\r\necho Apache Maven 3.9.14\r\n"
        } else {
            "#!/bin/sh\necho 'Apache Maven 3.9.14'\n"
        };
        let asdf_body = if cfg!(windows) {
            "@echo off\r\necho asdf\r\n"
        } else {
            "#!/bin/sh\necho 'asdf'\n"
        };
        write_fake_command(&bin_dir, "mvn", mvn_body);
        write_fake_command(&bin_dir, "asdf", asdf_body);
        let path = prepend_path(&bin_dir);
        let _path_guard = EnvVarGuard::set("PATH", path);
        let _cwd = CurrentDirGuard::enter(fixture.dir.path());

        let output = run_with(["ota", "doctor", "."]);
        let stdout = strip_ansi(&output.stdout);

        assert_eq!(output.exit_code, 1);
        assert!(stdout.contains("Version mismatch for tool: maven"));
        assert!(stdout.contains("maven resolved to `3.9.14`"));
        assert!(stdout.contains("contract requires `3.9.9`"));
        assert!(
            stdout.contains("install a compatible maven version that satisfies `3.9.9`")
                || stdout.contains("run `asdf install maven 3.9.9` and rerun `ota doctor`")
                || stdout.contains("run `mise install maven@3.9.9` and rerun `ota doctor`")
                || stdout.contains("install a compatible maven version")
        );
    }

